const canvas=document.getElementById('map'),ctx=canvas.getContext('2d');
const W=9,H=7,sqrt3=Math.sqrt(3),tiles=[],units=[];
const key=(q,r)=>q+','+r,inside=(q,r)=>q>=0&&q<W&&r>=0&&r<H;
const cities=[{q:1,r:3,name:'Dawnmere',owner:'player',capital:true},{q:7,r:2,name:'Frosthold',owner:'enemy',capital:true},{q:4,r:5,name:'Oldwatch',owner:'neutral'}];
let selected=null,mode='',turn=1,gold=120,food=80,renown=0,zoom=1,gameOver=false,anim=0;
const terrainAt=(q,r)=>{if((q===1&&r===3)||(q===7&&r===2)||(q===4&&r===5))return'city';const n=(q*17+r*29+q*r*13)%23;if(n===0||n===9)return'mountain';if(n===2||n===5||n===14||n===20)return'forest';if(n===7||n===18)return'water';return'plain'};
for(let q=0;q<W;q++)for(let r=0;r<H;r++)tiles.push({q,r,terrain:terrainAt(q,r)});
const makeUnit=(id,name,kind,q,r,team,hp=100)=>({id,name,kind,q,r,team,hp,maxHp:100,acted:false});
units.push(makeUnit('guard','Royal Guard','swords',2,3,'player'),makeUnit('ranger','Longbow Rangers','bow',2,5,'player'),makeUnit('rider','Dawn Riders','horse',3,2,'player'),makeUnit('pact1','Pact Legion','swords',6,2,'enemy'),makeUnit('pact2','Frost Wolves','horse',7,4,'enemy'),makeUnit('pact3','Pact Archers','bow',5,1,'enemy'));
const terrainNames={plain:'Grassland',forest:'Whispering woods',mountain:'Highland',water:'Deep water',city:'Settlement'};
function coord(q,r){const s=baseSize()*zoom;return{x:(sqrt3*s*(q+r/2)),y:1.5*s*r}}
let base=20,offset={x:0,y:0};function baseSize(){return base}
function resize(){const rect=canvas.getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.max(1,Math.round(rect.width*dpr));canvas.height=Math.max(1,Math.round(rect.height*dpr));ctx.setTransform(dpr,0,0,dpr,0,0);base=Math.max(11,Math.min(rect.width/(sqrt3*(W+2)),rect.height/(1.5*(H+1.5))));const s=base*zoom;const points=[coordRaw(0,0,s),coordRaw(W-1,H-1,s),coordRaw(W-1,0,s),coordRaw(0,H-1,s)];const minX=Math.min(...points.map(p=>p.x))-s*sqrt3/2,maxX=Math.max(...points.map(p=>p.x))+s*sqrt3/2,minY=-s,maxY=Math.max(...points.map(p=>p.y))+s;offset.x=(rect.width-(maxX-minX))/2-minX;offset.y=(rect.height-(maxY-minY))/2-minY;draw()}
function coordRaw(q,r,s){return{x:sqrt3*s*(q+r/2),y:1.5*s*r}}
function center(q,r){const p=coord(q,r);return{x:p.x+offset.x,y:p.y+offset.y}}
function hexPath(x,y,rad){ctx.beginPath();for(let i=0;i<6;i++){const a=Math.PI/180*(60*i-30),px=x+rad*Math.cos(a),py=y+rad*Math.sin(a);i?ctx.lineTo(px,py):ctx.moveTo(px,py)}ctx.closePath()}
const colors={plain:['#65764a','#7f8955'],forest:['#435a42','#566b48'],mountain:['#77796c','#969281'],water:['#3c6270','#52798a'],city:['#857248','#a28a56']};
function draw(){if(!ctx||!canvas.width)return;const rect=canvas.getBoundingClientRect(),w=rect.width,h=rect.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#28372b';ctx.fillRect(0,0,w,h);const s=base*zoom;for(const t of tiles){const {x,y}=center(t.q,t.r),[a,b]=colors[t.terrain];hexPath(x,y,s*.98);ctx.fillStyle=a;ctx.fill();ctx.strokeStyle='#c2bd8c29';ctx.lineWidth=1;ctx.stroke();hexPath(x,y-1,s*.82);ctx.fillStyle=b+'66';ctx.fill();drawTerrain(t,x,y,s)}
  cities.forEach(c=>drawCity(c,s));
  if(selected){const u=units.find(x=>x.id===selected);if(u){for(const t of tiles){const d=distance(u,t);if(d<=1&&u.team==='player'&&!u.acted){const p=center(t.q,t.r);ctx.beginPath();ctx.arc(p.x,p.y,s*.09,0,Math.PI*2);ctx.fillStyle='#e7d079aa';ctx.fill()}}}}
  for(const u of units)drawUnit(u,s);if(mode==='move'&&selected){const u=units.find(x=>x.id===selected);if(u){for(const t of tiles)if(canMove(u,t)){const p=center(t.q,t.r);hexPath(p.x,p.y,s*.89);ctx.fillStyle='#a9cd7950';ctx.fill();ctx.strokeStyle='#d5e59a99';ctx.stroke()}}}
}
function drawTerrain(t,x,y,s){ctx.save();ctx.translate(x,y);ctx.lineWidth=1;ctx.lineCap='round';if(t.terrain==='forest'){for(let i=0;i<3;i++){const dx=(i-1)*s*.28,dy=(i%2)*s*.14;ctx.fillStyle=i===1?'#293e31':'#344834';ctx.beginPath();ctx.moveTo(dx,dy-s*.34);ctx.lineTo(dx-s*.2,dy+s*.04);ctx.lineTo(dx+s*.2,dy+s*.04);ctx.closePath();ctx.fill();ctx.fillStyle='#574b36';ctx.fillRect(dx-s*.025,dy+s*.02,s*.05,s*.14)}}else if(t.terrain==='mountain'){ctx.fillStyle='#64685e';ctx.beginPath();ctx.moveTo(-s*.36,s*.16);ctx.lineTo(-s*.1,-s*.34);ctx.lineTo(s*.25,s*.17);ctx.closePath();ctx.fill();ctx.fillStyle='#aaa691';ctx.beginPath();ctx.moveTo(-s*.1,-s*.34);ctx.lineTo(s*.01,-s*.04);ctx.lineTo(-s*.12,-s*.1);ctx.closePath();ctx.fill();ctx.beginPath();ctx.moveTo(s*.02,s*.2);ctx.lineTo(s*.27,-s*.17);ctx.lineTo(s*.43,s*.2);ctx.closePath();ctx.fillStyle='#77796d';ctx.fill()}else if(t.terrain==='water'){ctx.strokeStyle='#a3c6c344';ctx.beginPath();ctx.moveTo(-s*.25,0);ctx.quadraticCurveTo(0,-s*.08,s*.22,0);ctx.stroke();ctx.beginPath();ctx.moveTo(-s*.15,s*.17);ctx.quadraticCurveTo(s*.08,s*.09,s*.3,s*.17);ctx.stroke()}else if(t.terrain==='plain'){const n=(t.q*7+t.r*11)%4;ctx.fillStyle='#d2c68b4d';for(let i=0;i<n;i++){let dx=((i*43+t.q*13)%25-12)*s/30,dy=((i*31+t.r*9)%21-10)*s/28;ctx.fillRect(dx,dy,s*.035,s*.035)}}ctx.restore()}
function drawCity(c,s){const p=center(c.q,c.r),mine=c.owner==='player',enemy=c.owner==='enemy';ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='#151a13aa';ctx.beginPath();ctx.ellipse(0,s*.15,s*.48,s*.2,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=mine?'#b68a44':enemy?'#7596a1':'#9a967b';ctx.fillRect(-s*.31,-s*.12,s*.62,s*.29);ctx.fillStyle='#bdac7e';ctx.fillRect(-s*.28,-s*.25,s*.56,s*.14);ctx.fillStyle=mine?'#e1ba62':enemy?'#a1cad4':'#c3c0a8';ctx.fillRect(-s*.1,-s*.47,s*.2,s*.32);ctx.fillStyle=mine?'#873f32':enemy?'#496d83':'#77745e';ctx.beginPath();ctx.moveTo(-s*.14,-s*.47);ctx.lineTo(s*.15,-s*.47);ctx.lineTo(s*.11,-s*.68);ctx.lineTo(-s*.1,-s*.68);ctx.closePath();ctx.fill();ctx.fillStyle='#ffdfa1';ctx.font=`${Math.max(8,s*.22)}px DM Mono`;ctx.textAlign='center';ctx.fillText(c.name,0,s*.49);ctx.restore()}
const unitIcons={swords:'⚔',bow:'➶',horse:'♞'};
function drawUnit(u,s){const p=center(u.q,u.r),own=u.team==='player',picked=selected===u.id;ctx.save();ctx.translate(p.x,p.y-s*.05);ctx.shadowColor='#080c09';ctx.shadowBlur=6;ctx.fillStyle=own?'#b68843':'#597f91';ctx.beginPath();ctx.arc(0,0,s*.28,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle=picked?'#fff0ad':own?'#efcf83':'#b4d5dc';ctx.lineWidth=picked?2.3:1.2;ctx.stroke();ctx.fillStyle='#171d17';ctx.font=`${s*.31}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(unitIcons[u.kind],0,0);if(u.acted&&own){ctx.beginPath();ctx.arc(s*.21,-s*.2,s*.065,0,Math.PI*2);ctx.fillStyle='#707b64';ctx.fill()}ctx.fillStyle='#10150f';ctx.fillRect(-s*.3,s*.29,s*.6,s*.065);ctx.fillStyle=u.team==='player'?'#d8b15c':'#719bad';ctx.fillRect(-s*.3,s*.29,s*.6*Math.max(0,u.hp/u.maxHp),s*.065);ctx.restore()}

