function distance(a,b){const aq=a.q,ar=a.r-Math.floor(a.q/2),bq=b.q,br=b.r-Math.floor(b.q/2);return(Math.abs(aq-bq)+Math.abs(ar-br)+Math.abs(aq+ar-bq-br))/2}
function occupant(q,r,except){return units.find(u=>u.id!==except&&u.q===q&&u.r===r)}
function canMove(u,t){return !u.acted&&u.team==='player'&&distance(u,t)===1&&!['water','mountain'].includes(t.terrain)&&!occupant(t.q,t.r,u.id)}
function addLog(text){const log=document.getElementById('log'),line=document.createElement('div');line.className='log-line';line.innerHTML=text;log.prepend(line);while(log.children.length>8)log.lastChild.remove()}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2100)}
function cityAt(q,r){return cities.find(c=>c.q===q&&c.r===r)}
function capture(u){const c=cityAt(u.q,u.r);if(c&&c.owner!==u.team){c.owner=u.team;if(u.team==='player'){renown+=35;gold+=35;toast(`${c.name} is yours! +35 renown`);addLog(`<em>${c.name}</em> has joined your realm.`)}else{toast(`${c.name} has fallen to the Iron Pact`);addLog(`The Pact seized <em>${c.name}</em>.`)}}}
function refresh(){document.getElementById('turn').textContent=String(turn).padStart(2,'0');document.getElementById('gold').textContent=gold;document.getElementById('food').textContent=food;document.getElementById('renown').textContent=renown;const held=cities.filter(c=>c.owner==='player').length;document.getElementById('progress').style.width=`${Math.min(100,18+held*41+renown*.12)}%`;document.getElementById('armyCount').textContent=`${units.filter(u=>u.team==='player').length} BANNERS`;document.getElementById('armyList').innerHTML=units.filter(u=>u.team==='player').map(u=>`<div class="army-token" data-unit="${u.id}"><span class="army-emoji">${unitIcons[u.kind]}</span><div><div class="army-count">${u.hp}</div><div class="army-label">${u.name.split(' ')[0]}</div></div></div>`).join('');document.querySelectorAll('.army-token').forEach(el=>el.onclick=()=>selectUnit(el.dataset.unit));document.getElementById('endTurn').disabled=gameOver;updateCommand();draw()}
function updateCommand(){const u=units.find(x=>x.id===selected);const name=document.getElementById('unitName'),sub=document.getElementById('unitSub'),tag=document.getElementById('selectedTag'),stats=document.getElementById('unitStats'),health=document.getElementById('healthBar');if(!u){name.textContent='Choose a unit';sub.textContent='Tap one of your banners on the map';tag.textContent='NO UNIT';stats.innerHTML='<div class="stat"><b>—</b><small>Health</small></div><div class="stat"><b>—</b><small>Strength</small></div><div class="stat"><b>—</b><small>Move</small></div>';health.style.width='0%'}else{name.textContent=u.name;sub.textContent=(u.team==='player'?'YOUR FORCES':'IRON PACT')+' · '+terrainNames[tiles.find(t=>t.q===u.q&&t.r===u.r).terrain];tag.textContent=u.acted?'MUSTERED':'READY';const strength=u.kind==='horse'?34:u.kind==='bow'?25:30;stats.innerHTML=`<div class="stat"><b>${u.hp}<small> / 100</small></b><small>Health</small></div><div class="stat"><b>${strength}</b><small>Strength</small></div><div class="stat"><b>${u.acted?'Spent':'1 tile'}</b><small>Move</small></div>`;health.style.width=u.hp+'%';health.style.background=u.hp<35?'#d2785e':'#a9c27c'}const friendly=u&&u.team==='player'&&!u.acted&&!gameOver;document.getElementById('moveBtn').disabled=!friendly;document.getElementById('attackBtn').disabled=!friendly;document.getElementById('healBtn').disabled=!friendly;document.getElementById('moveBtn').textContent=mode==='move'?'✕ Cancel':'⇢ Move'}
function selectUnit(id){selected=id;mode='';updateCommand();draw()}
function moveUnit(u,t){if(!canMove(u,t))return false;u.q=t.q;u.r=t.r;u.acted=true;mode='';capture(u);selected=u.id;addLog(`<em>${u.name}</em> advances to ${terrainNames[t.terrain].toLowerCase()}.`);if(cities[1].owner==='player'){gameOver=true;showModal('VICTORY','The Northreach is yours','Frosthold has fallen. The Iron Pact retreats beyond the mountains. Your people will remember this day.')}refresh();return true}
function attack(attacker,target){if(!attacker||!target||attacker.acted||attacker.team===target.team)return false;const range=attacker.kind==='bow'?2:1;if(distance(attacker,target)>range)return false;const strength=attacker.kind==='horse'?34:attacker.kind==='bow'?26:31;const terrain=tiles.find(t=>t.q===target.q&&t.r===target.r).terrain;let damage=strength+(Math.random()*12|0)+(attacker.team==='player'?3:0);if(terrain==='forest')damage=Math.max(12,damage-7);target.hp-=damage;attacker.acted=true;mode='';addLog(`<em>${attacker.name}</em> strikes ${target.name} for ${damage}.`);toast(`${attacker.name} dealt ${damage} damage`);if(target.hp<=0){addLog(`<em>${target.name}</em> has been routed.`);if(attacker.team==='player')renown+=12;units.splice(units.indexOf(target),1);if(selected===target.id)selected=attacker.id}refresh();return true}
function onMapClick(ev){if(gameOver)return;const rect=canvas.getBoundingClientRect(),x=ev.clientX-rect.left,y=ev.clientY-rect.top;let best=null,bd=Infinity;for(const t of tiles){const p=center(t.q,t.r),d=Math.hypot(p.x-x,p.y-y);if(d<bd){bd=d;best=t}}if(!best||bd>base*zoom*.88)return;const u=occupant(best.q,best.r);if(u){if(u.team==='player'){selectUnit(u.id);return}const active=units.find(z=>z.id===selected);if(mode==='attack'&&active){if(!attack(active,u))toast('Target is out of range');return}if(active&&active.team==='player'&&distance(active,u)<=(active.kind==='bow'?2:1)){if(attack(active,u))return}selected=null;mode='';updateCommand();draw();return}const active=units.find(z=>z.id===selected);if(active&&mode==='move'){if(moveUnit(active,best))return;toast('Cannot move there');return}selected=null;mode='';updateCommand();draw()}

