function onMapClick(ev){if(gameOver)return;const rect=canvas.getBoundingClientRect(),x=ev.clientX-rect.left,y=ev.clientY-rect.top;let best=null,bd=Infinity;for(const t of tiles){const p=center(t.q,t.r),d=Math.hypot(p.x-x,p.y-y);if(d<bd){bd=d;best=t}}if(!best||bd>base*zoom*.88)return;const u=occupant(best.q,best.r);if(u){if(u.team==='player'){selectUnit(u.id);return}const active=units.find(z=>z.id===selected);if(mode==='attack'&&active){if(!attack(active,u))toast('Target is out of range');return}if(active&&active.team==='player'&&distance(active,u)<=(active.kind==='bow'?2:1)){if(attack(active,u))return}selected=null;mode='';updateCommand();draw();return}const active=units.find(z=>z.id===selected);if(active&&mode==='move'){if(moveUnit(active,best))return;toast('Cannot move there');return}selected=null;mode='';updateCommand();draw()}
