function toast(text){const node=el('toast');node.textContent=text;node.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.classList.remove('show'),2100)}
function showModal(kicker,title,text){el('modalEyebrow').textContent=kicker;el('modalTitle').textContent=title;el('modalText').textContent=text;el('overlay').classList.add('show')}
function capture(unit){const city=cityAt(unit.q,unit.r);if(!city||city.owner===unit.team)return;city.owner=unit.team;if(unit.team==='player'){renown+=35;gold+=35;toast(`${city.name} is yours! +35 renown`);addLog(`<em>${city.name}</em> has joined your realm.`);if(city.name==='Frosthold'){gameOver=true;showModal('VICTORY','The Northreach is yours','Frosthold has fallen. The Iron Pact retreats beyond the mountains. Your people will remember this day.')}}else{toast(`${city.name} has fallen to the Iron Pact`);addLog(`The Pact seized <em>${city.name}</em>.`)}}
function canMove(unit,tile){return !unit.acted&&unit.team==='player'&&distance(unit,tile)===1&&!['water','mountain'].includes(tile.terrain)&&!unitAt(tile.q,tile.r,unit.id)}
function selectUnit(id){selected=id;mode='';refresh()}
function attack(attacker,target){if(!attacker||!target||attacker.acted||attacker.team===target.team)return false;const range=attacker.kind==='bow'?2:1;if(distance(attacker,target)>range)return false;const terrain=at(target.q,target.r)?.terrain;const strength=attacker.kind==='horse'?34:attacker.kind==='bow'?26:31;let damage=strength+Math.floor(Math.random()*12)+(attacker.team==='player'?3:0);if(terrain==='forest')damage=Math.max(12,damage-7);target.hp-=damage;attacker.acted=true;mode='';addLog(`<em>${attacker.name}</em> strikes ${target.name} for ${damage}.`);toast(`${attacker.name} dealt ${damage} damage`);if(target.hp<=0){addLog(`<em>${target.name}</em> has been routed.`);if(attacker.team==='player')renown+=12;units.splice(units.indexOf(target),1);if(selected===target.id)selected=attacker.id}refresh();return true}
function moveUnit(unit,tile){if(!canMove(unit,tile))return false;unit.q=tile.q;unit.r=tile.r;unit.acted=true;mode='';capture(unit);addLog(`<em>${unit.name}</em> advances to ${terrainNames[tile.terrain].toLowerCase()}.`);selected=unit.id;refresh();return true}
function onMapClick(event){if(gameOver)return;const rect=canvas.getBoundingClientRect(),x=event.clientX-rect.left,y=event.clientY-rect.top;let nearest=null,dist=Infinity;for(const tile of tiles){const p=pos(tile.q,tile.r),d=Math.hypot(p.x-x,p.y-y);if(d<dist){dist=d;nearest=tile}}if(!nearest||dist>base*zoom*.88)return;const target=unitAt(nearest.q,nearest.r);const active=units.find(unit=>unit.id===selected);if(target){if(target.team==='player'){selectUnit(target.id);return}if(mode==='attack'&&active){if(!attack(active,target))toast('Target is out of range');return}if(active?.team==='player'&&distance(active,target)<=(active.kind==='bow'?2:1)){if(attack(active,target))return}selected=null;mode='';refresh();return}if(active&&mode==='move'){if(moveUnit(active,nearest))return;toast('Cannot move there');return}selected=null;mode='';refresh()}
function updateCommand(){const unit=units.find(item=>item.id===selected),name=el('unitName'),sub=el('unitSub'),tag=el('selectedTag'),stats=el('unitStats'),health=el('healthBar');if(!unit){name.textContent='Choose a unit';sub.textContent='Tap one of your banners on the map';tag.textContent='NO UNIT';stats.innerHTML='<div class="stat"><b>—</b><small>Health</small></div><div class="stat"><b>—</b><small>Strength</small></div><div class="stat"><b>—</b><small>Move</small></div>';health.style.width='0%'}else{name.textContent=unit.name;sub.textContent=(unit.team==='player'?'YOUR FORCES':'IRON PACT')+' · '+terrainNames[at(unit.q,unit.r).terrain];tag.textContent=unit.acted?'MUSTERED':'READY';const strength=unit.kind==='horse'?34:unit.kind==='bow'?26:31;stats.innerHTML=`<div class="stat"><b>${unit.hp}<small> / 100</small></b><small>Health</small></div><div class="stat"><b>${strength}</b><small>Strength</small></div><div class="stat"><b>${unit.acted?'Spent':'1 tile'}</b><small>Move</small></div>`;health.style.width=`${Math.max(0,unit.hp)}%`;health.style.background=unit.hp<35?'#d2785e':'#a9c27c'}const ready=!!unit&&unit.team==='player'&&!unit.acted&&!gameOver;el('moveBtn').disabled=!ready;el('attackBtn').disabled=!ready;el('healBtn').disabled=!ready;el('moveBtn').textContent=mode==='move'?'✕ Cancel':'⇢ Move';el('attackBtn').textContent=mode==='attack'?'✕ Cancel':'⚔ Attack'}
function refresh(){el('turn').textContent=String(turn).padStart(2,'0');el('gold').textContent=gold;el('food').textContent=food;el('renown').textContent=renown;const held=cities.filter(city=>city.owner==='player').length;el('progress').style.width=`${Math.min(100,18+held*41+renown*.12)}%`;el('armyCount').textContent=`${units.filter(unit=>unit.team==='player').length} BANNERS`;el('armyList').innerHTML=units.filter(unit=>unit.team==='player').map(unit=>`<button class="army-token" data-unit="${unit.id}" aria-label="Select ${unit.name}"><span class="army-emoji">${icons[unit.kind]}</span><span><span class="army-count">${unit.hp}</span><span class="army-label">${unit.name.split(' ')[0]}</span></span></button>`).join('');el('armyList').querySelectorAll('.army-token').forEach(button=>button.addEventListener('click',()=>selectUnit(button.dataset.unit)));el('endTurn').disabled=gameOver;el('recruitBtn').disabled=gameOver||gold<55||food<25;updateCommand();draw()}
function enemyTurn(){for(const foe of units.filter(unit=>unit.team==='enemy')){if(!units.includes(foe)||gameOver)continue;const targets=units.filter(unit=>unit.team==='player');if(!targets.length)break;const inRange=targets.filter(unit=>distance(foe,unit)<=(foe.kind==='bow'?2:1)).sort((a,b)=>a.hp-b.hp)[0];if(inRange){attack(foe,inRange);continue}const target=targets.sort((a,b)=>distance(foe,a)-distance(foe,b))[0];const steps=tiles.filter(tile=>!['water','mountain'].includes(tile.terrain)&&!unitAt(tile.q,tile.r,foe.id)&&distance(foe,tile)===1).sort((a,b)=>distance(a,target)-distance(b,target));if(steps.length){foe.q=steps[0].q;foe.r=steps[0].r;capture(foe);addLog(`<em>${foe.name}</em> advances.`);const victim=units.find(unit=>unit.team==='player'&&distance(foe,unit)<=(foe.kind==='bow'?2:1));if(victim)attack(foe,victim)}}if(cities[0].owner==='enemy'){gameOver=true;showModal('DEFEAT','Dawnmere has fallen','The Iron Pact has broken through your defenses. Rally your forces and try a new campaign.')}if(!gameOver){turn++;gold+=18+cities.filter(city=>city.owner==='player').length*8;food+=16;for(const unit of units.filter(item=>item.team==='player')){unit.acted=false;unit.hp=Math.min(100,unit.hp+7)}el('era').textContent=turn>5?'· AGE OF IRON':'· AGE OF ASH';addLog(`<em>Turn ${turn}</em> begins. Your realm gathers provisions and gold.`)}refresh()}
function recruit(){if(gold<55||food<25||gameOver){toast('Not enough resources to recruit');return}const occupied=tiles.filter(tile=>distance(tile,{q:1,r:3})===1&&!['water','mountain'].includes(tile.terrain)&&!unitAt(tile.q,tile.r));if(!occupied.length){toast('No room beside Dawnmere to muster a banner');return}const tile=occupied[0];gold-=55;food-=25;const unit=makeUnit(`militia${turn}-${units.length}`,`Dawn Militia ${units.filter(item=>item.team==='player').length+1}`,'swords',tile.q,tile.r,'player');unit.acted=true;units.push(unit);selected=unit.id;addLog(`<em>${unit.name}</em> joins the legion.`);toast('A new banner joins your ranks');refresh()}
function rest(){const unit=units.find(item=>item.id===selected);if(!unit||unit.team!=='player'||unit.acted||gameOver)return;if(unit.hp>=100){toast('This banner is already at full strength');return}if(food<12){toast('Not enough provisions to rest');return}food-=12;unit.hp=Math.min(100,unit.hp+38);unit.acted=true;mode='';addLog(`<em>${unit.name}</em> rests and recovers.`);toast('Rested · recovered strength');refresh()}
function showHelp(){showModal('FIELD MANUAL','How to play','Select a gold banner, then Move and tap a highlighted neighboring hex. Attack nearby Iron Pact units (archers can reach two hexes). Rest restores health for provisions. Recruit from the Legion panel. Capture Frosthold to win — but keep Dawnmere safe. End your turn to gather resources and let the Pact move.')}
function endTurn(){if(gameOver)return;selected=null;mode='';for(const enemy of units.filter(unit=>unit.team==='enemy'))enemy.acted=false;enemyTurn()}
canvas.addEventListener('click',onMapClick);el('moveBtn').addEventListener('click',()=>{const unit=units.find(item=>item.id===selected);if(!unit||unit.acted)return;mode=mode==='move'?'':'move';updateCommand();draw()});el('attackBtn').addEventListener('click',()=>{const unit=units.find(item=>item.id===selected);if(!unit||unit.acted)return;mode=mode==='attack'?'':'attack';updateCommand();draw();if(mode==='attack')toast(unit.kind==='bow'?'Choose an enemy within two hexes':'Choose an adjacent enemy')});el('healBtn').addEventListener('click',rest);el('recruitBtn').addEventListener('click',recruit);el('endTurn').addEventListener('click',endTurn);el('helpBtn').addEventListener('click',showHelp);el('modalClose').addEventListener('click',()=>el('overlay').classList.remove('show'));el('overlay').addEventListener('click',event=>{if(event.target===el('overlay'))el('overlay').classList.remove('show')});el('zoomIn').addEventListener('click',()=>{zoom=Math.min(1.35,zoom+.1);fit()});el('zoomOut').addEventListener('click',()=>{zoom=Math.max(.75,zoom-.1);fit()});el('soundBtn').addEventListener('click',event=>{const btn=event.currentTarget,muted=btn.getAttribute('aria-pressed')==='true';btn.setAttribute('aria-pressed',String(!muted));btn.textContent=muted?'♪':'♩';toast(muted?'Sound cues enabled':'Sound cues muted')});
canvas.addEventListener('wheel',event=>{event.preventDefault();zoom=Math.max(.75,Math.min(1.35,zoom+(event.deltaY<0?.08:-.08)));fit()},{passive:false});window.addEventListener('resize',fit);if('ResizeObserver'in window)new ResizeObserver(fit).observe(canvas);addLog('<em>The Northreach</em> stands at the edge of war.');addLog('Capture Frosthold. Protect Dawnmere.');refresh();fit();
})();

