const { createRequire } = require('node:module');
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox', '--disable-dev-shm-usage'] });
  const errors = [];
  for (const [name, viewport] of [['desktop', {width: 1280, height: 800}], ['mobile', {width: 390, height: 844}]]) {
    const page = await browser.newPage({ viewport, deviceScaleFactor: 1, isMobile: name === 'mobile', hasTouch: name === 'mobile' });
    page.on('pageerror', error => errors.push(`${name}: ${error.message}`));
    await page.goto('http://localhost:3000', { waitUntil: 'networkidle', timeout: 30000 });
    await page.screenshot({ path: `screenshots/${name}.jpg`, type: 'jpeg', quality: 68 });
    const state = await page.evaluate(() => ({
      title: document.title,
      canvas: [document.querySelector('#map').width, document.querySelector('#map').height],
      viewport: [innerWidth, innerHeight],
      bodyScroll: [document.documentElement.scrollWidth, document.documentElement.scrollHeight],
      visibleMap: document.querySelector('.world-wrap').getBoundingClientRect().toJSON(),
      army: document.querySelectorAll('.army-token').length,
      endTurnVisible: !!document.querySelector('#endTurn').getBoundingClientRect().height
    }));
    await page.locator('.army-token').first().click();
    await page.locator('#moveBtn').click();
    const moveMode = await page.locator('#moveBtn').textContent();
    await page.locator('#moveBtn').click();
    await page.locator('#helpBtn').click();
    const helpOpened = await page.locator('#overlay').evaluate(el => getComputedStyle(el).display !== 'none');
    await page.locator('#modalClose').click();
    await page.locator('#endTurn').click();
    const turn = await page.locator('#turn').textContent();
    console.log(JSON.stringify({name, state, moveMode, helpOpened, turn}));
