  const p=await b.newPage({viewport,isMobile:viewport.width<650}); await p.goto('http://localhost:3000');
  console.log(await p.evaluate(() => {const r=s=>{const x=document.querySelector(s).getBoundingClientRect();return {x:Math.round(x.x),y:Math.round(x.y),w:Math.round(x.width),h:Math.round(x.height),right:Math.round(x.right),bottom:Math.round(x.bottom)}};return {vp:[innerWidth,innerHeight],doc:[document.documentElement.scrollWidth,document.documentElement.scrollHeight],header:r('.topbar'),brand:r('.brand'),turn:r('.turn-box'),resources:r('.resources'),actions:r('.top-actions'),main:r('.main'),map:r('.world-wrap'),side:r('.side'),objective:r('.objective-card'),command:r('.selected-card'),army:r('.units-card'),log:r('.log-card'),end:r('#endTurn')}}));
  await p.close();
 }
 await b.close();
})();
