const { createRequire } = require('node:module');
const req = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = req('playwright');
(async () => {
 const b = await chromium.launch({executablePath:'/usr/bin/chromium', args:['--no-sandbox','--disable-dev-shm-usage']});
 for (const viewport of [{width:320,height:568},{width:375,height:667},{width:390,height:844},{width:844,height:390},{width:667,height:375},{width:1280,height:800}]) {
  const p=await b.newPage({viewport,isMobile:viewport.width<650,hasTouch:viewport.width<650}); await p.goto('http://localhost:3000');
  console.log(await p.evaluate(() => {const r=s=>{const x=document.querySelector(s).getBoundingClientRect();return {x:Math.round(x.x),y:Math.round(x.y),w:Math.round(x.width),h:Math.round(x.height),right:Math.round(x.right),bottom:Math.round(x.bottom)}};return {vp:[innerWidth,innerHeight],doc:[document.documentElement.scrollWidth,document.documentElement.scrollHeight],header:r('.topbar'),main:r('.main'),map:r('.world-wrap'),side:r('.side'),objective:r('.objective-card'),command:r('.selected-card'),army:r('.units-card'),log:r('.log-card'),end:r('#endTurn')}}));
  await p.close();
 }
 await b.close();
})();
