input.command:
node <<'NODE'
const { createRequire } = require('node:module');
const req = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = req('playwright');
(async () => {
 const b = await chromium.launch({executablePath:'/usr/bin/chromium', args:['--no-sandbox','--disable-dev-shm-usage']});
 const errors=[];
 for (const [name,viewport] of [['desktop',{width:1280,height:800}],['mobile',{width:390,height:844}],['narrow',{width:320,height:568}],['landscape',{width:844,height:390}]]) {
  const p=await b.newPage({viewport,isMobile:viewport.width<650,hasTouch:viewport.width<650});
  p.on('pageerror',e=>errors.push(`${name}: ${e.message}`));
  await p.goto('http://localhost:3000',{waitUntil:'networkidle'});
  if (name==='desktop'||name==='mobile') await p.screenshot({path:`screenshots/${name}.jpg`,type:'jpeg',quality:68});
  const layout=await p.evaluate(()=>{const box=s=>{const r=document.querySelector(s).getBoundingClientRect();return [Math.round(r.x),Math.round(r.y),Math.round(r.width),Math.round(r.height),Math.round(r.right),Math.round(r.bottom)]};return {viewport:[innerWidth,innerHeight],document:[document.documentElement.scrollWidth,document.documentElement.scrollHeight],header:box('.topbar'),main:box('.main'),map:box('.world-wrap'),side:box('.side'),cards:['.objective-card','.selected-card','.units-card','.log-card','#endTurn'].map(s=>[s,box(s)])}});
  if (name==='mobile') {
   await p.locator('.army-token').first().click(); await p.locator('#moveBtn').click(); const move=await p.locator('#moveBtn').textContent(); await p.locator('#moveBtn').click(); await p.locator('#helpBtn').click(); const help=await p.locator('#overlay').evaluate(x=>getComputedStyle(x).display!=='none'); await p.locator('#modalClose').click(); await p.locator('#endTurn').click(); console.log(JSON.stringify({name,layout,move,help,turn:await p.locator('#turn').textContent()}));
  } else console.log(JSON.stringify({name,layout}));
  await p.close();
 }
 await b.close(); console.log(JSON.stringify({errors})); if(errors.length)process.exitCode=1;
})().catch(e=>{console.error(e);process.exitCode=1});
NODE

