const { createRequire } = require('node:module');
const req = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = req('playwright');
(async () => {
 const b = await chromium.launch({executablePath:'/usr/bin/chromium', args:['--no-sandbox','--disable-dev-shm-usage']});
 const errors=[];
 for (const [name, viewport] of [['desktop',{width:1280,height:800}],['mobile',{width:390,height:844}],['narrow',{width:320,height:568}],['landscape',{width:844,height:390}],['small-landscape',{width:667,height:375}]]) {
  const mobile = viewport.width < 651;
  const p = await b.newPage({viewport,isMobile:mobile,hasTouch:true});
  p.on('pageerror', e => errors.push(`${name}: ${e.message}`));
  await p.goto('http://localhost:3000',{waitUntil:'networkidle'});
  if (name==='desktop' || name==='mobile') await p.screenshot({path:`screenshots/${name}.jpg`,type:'jpeg',quality:68});
  const layout = await p.evaluate(() => {
   const box = s => { const e=document.querySelector(s),r=e.getBoundingClientRect();return {x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height),right:Math.round(r.right),bottom:Math.round(r.bottom),clientH:e.clientHeight,scrollH:e.scrollHeight}; };
   return {vp:[innerWidth,innerHeight],doc:[document.documentElement.scrollWidth,document.documentElement.scrollHeight],header:box('.topbar'),main:box('.main'),map:box('.world-wrap'),side:box('.side'),objective:box('.objective-card'),command:box('.selected-card'),army:box('.units-card'),log:box('.log-card'),end:box('#endTurn'),help:box('#helpBtn'),sound:box('#soundBtn')};
  });
  const buttons = await p.locator('button').evaluateAll(bs=>bs.map(x=>({id:x.id||x.className,disabled:x.disabled,rect:(()=>{let r=x.getBoundingClientRect();return [Math.round(r.left),Math.round(r.top),Math.round(r.right),Math.round(r.bottom)]})()})));
  let play={};
  if (mobile) {
   await p.locator('.army-token').first().click();
   await p.locator('#moveBtn').click(); play.moveMode=await p.locator('#moveBtn').textContent();
   await p.locator('#moveBtn').click();
   await p.locator('#helpBtn').click(); play.helpVisible=await p.locator('#overlay').evaluate(x=>getComputedStyle(x).display!=='none');
   await p.locator('#modalClose').click();
   await p.locator('#endTurn').click(); play.turn=await p.locator('#turn').textContent();
   if (name==='narrow') {
    await p.locator('.side').evaluate(e=>e.scrollTop=e.scrollHeight);
    play.narrowEndReachable=await p.locator('#endTurn').evaluate(e=>{let r=e.getBoundingClientRect();return r.height>0&&r.top>=0&&r.bottom<=innerHeight});
   }
  }
  console.log(JSON.stringify({name,layout,buttons,play}));
  await p.close();
 }
 await b.close();
 console.log(JSON.stringify({errors})); if(errors.length) process.exitCode=1;
})().catch(e=>{console.error(e);process.exitCode=1});
